package net.wtworkshop.gametest;
import java.util.*;import net.minecraft.gametest.framework.*;import net.minecraft.world.item.*;import net.neoforged.neoforge.gametest.*;import net.wtworkshop.tool.*;import net.wtworkshop.station.*;
@GameTestHolder("wt_workshop") @PrefixGameTestTemplate(false)
public final class AddonApiTests {
 @GameTest(template="empty") public static void unavailableAddonRetainsSlotAndData(GameTestHelper h){String id="missing_addon:example";var d=ToolData.of("iron","wood","string").withAddonSlot(id,Modifier.Slot.ABILITY).withModifierAdded(id).withProgress("missing_addon:partial",3).withXp(2,44).withExpansion("copper");var tool=WorkshopTool.create(ToolType.SWORD,d);h.assertTrue(WorkshopTool.stats(tool).usedAbilities()==1,"Missing addon freed ability slot");var ops=h.getLevel().registryAccess().createSerializationContext(net.minecraft.nbt.NbtOps.INSTANCE);var copy=ItemStack.CODEC.parse(ops,ItemStack.CODEC.encodeStart(ops,tool).getOrThrow()).getOrThrow();h.assertTrue(WorkshopTool.data(copy).equals(d),"Addon data lost in item save");var b=io.netty.buffer.Unpooled.buffer();try{ToolData.STREAM_CODEC.encode(b,d);h.assertTrue(ToolData.STREAM_CODEC.decode(b).equals(d),"Addon slot network roundtrip failed");}finally{b.release();}h.assertTrue(d.withProgress(Modifier.HASTE,3).withXp(3,0).withMaterial(net.wtworkshop.material.PartRole.HANDLE,"wood").addonSlots().equals(d.addonSlots()),"Mutation lost slot metadata");var result=StationLogic.compute(List.of(ItemStack.EMPTY,ItemStack.EMPTY,ItemStack.EMPTY,copy,new ItemStack(Items.SPONGE)),h.getLevel());h.assertTrue(result.success()&&WorkshopTool.stats(result.result()).usedAbilities()==0&&WorkshopTool.data(result.result()).expansionTier()==1,"Missing addon cannot be removed safely");h.succeed();}
}
